        /**
         * Get output variables as a dictionary
         * This function returns all variables in the schema with variable_type "output".
         *
         * Keep the function signature the same. Do not remove the function.
         *
         * @return {Object} Dictionary of all output variables with their values. The keys are the variable names (strs).
         */
        let a = 0;

        function getOutputVariables() {
            return { "a": a };
        }

        /**
         * The input variables defined in the variables schema -- all variables with variable_type "input". These values can
         * be configured to parameterize the diagram.
         */
        const INPUT_VARIABLES = {"m": 2};

        // Wrap in DOMContentLoaded to ensure the diagram library is fully loaded before running the code.
        addEventListener("DOMContentLoaded", () => {
            let dynamicPoint;

            // Create a grid system
            // Using MULTI_QUADRANT_SMALL (10x7) as requested.
            // Range needs to accommodate y=4 (when a=3) and y=-4 (possible for m=-3).
            // xAxisMin: -5 to 5 (width 10).
            // yAxisMin: -3 to 4 (height 7). This fits the dynamic point range [-2, 4].
            const grid = new Grid2D({
                gridSize: "MULTI_QUADRANT_SMALL",
                xAxisMin: -5,
                yAxisMin: -3,
                xAxisLabels: true,
                yAxisLabels: true,
                showGrid: true,
                showAxes: true,
                slider: {
                    min: -3,
                    max: 3,
                    step: 1,
                    valueToCallBack: {
                        0: (val) => {
                            a = val;
                            // Update the dynamic point for Line 2 (y = ax + 1)
                            // At x=1, y = a + 1
                            if (dynamicPoint) {
                                dynamicPoint.update({ newX: 1, newY: val + 1 });
                            }
                        },
                    },
                },
            });

            // Create a new math diagram
            const diagram = new MathDiagram({
                container: "#diagram",
                grid: grid,
            });

            const m = INPUT_VARIABLES.m;

            // --- Line 1 (Static): y = mx - 1 ---
            // Create invisible points to define the line
            const line1P1 = diagram.addPoint({
                x: 0,
                y: -1,
                visible: false,
                isStatic: true,
            });

            const line1P2 = diagram.addPoint({
                x: 1,
                y: m - 1,
                visible: false,
                isStatic: true,
            });

            diagram.addLine({
                point1: line1P1,
                point2: line1P2,
                type: "line",
            });

            // --- Line 2 (Dynamic): y = ax + 1 ---
            // Create visible plotted points as requested
            const line2P1 = diagram.addPoint({
                x: 0,
                y: 1,
                visible: true,
                isStatic: true, // This point serves as the pivot and does not move
            });

            // The dynamic point at (1, a+1)
            // Initial a is 0, so y = 1
            dynamicPoint = diagram.addPoint({
                x: 1,
                y: a + 1,
                visible: true,
                isStatic: true, // Controlled by slider, not draggable directly
            });

            diagram.addLine({
                point1: line2P1,
                point2: dynamicPoint,
                type: "line",
            });
        });

        // Scale diagram on load and on resize
        window.onload = window.scaleDiagram;
        window.addEventListener("resize", window.scaleDiagram);
    </script>
